  // 2.8 — Google account without setup (Android Backup)
  'Welcome back — your data was restored from your Google account': 'Bon retour — vos données ont été restaurées depuis votre compte Google',
  'Google Drive isn’t set up for this version of the app yet — your data is still saved to your Google account through Android Backup.': 'Google Drive n’est pas encore configuré pour cette version de l’app — vos données sont tout de même enregistrées dans votre compte Google via la sauvegarde Android.',
  'Saved privately to your Google account — only MAHDI-JYM can read it. Sign out anytime in Settings.': 'Enregistré en privé dans votre compte Google — seule MAHDI-JYM peut le lire. Déconnexion à tout moment dans les Réglages.',
  'Everything is saved to your Google account automatically through Android Backup, and comes back when you install MAHDI-JYM again.': 'Tout est enregistré automatiquement dans votre compte Google via la sauvegarde Android, et revient quand vous réinstallez MAHDI-JYM.',
  'Now saved to Google Drive': 'Désormais enregistré dans Google Drive',
  'Your data stays on this phone. Changes are no longer saved to your Google account.': 'Vos données restent sur ce téléphone. Les modifications ne sont plus enregistrées dans votre compte Google.',
  'Sign in with a Google account that’s already on this phone — no password. Everything is then saved to that account automatically.': 'Connectez-vous avec un compte Google déjà présent sur ce téléphone — sans mot de passe. Tout est ensuite enregistré automatiquement dans ce compte.',
  'Workouts, plan, steps, water, body weight and settings are saved through Android Backup to your Google account. Android uploads it in the background, usually within a few hours, and puts it back when you install MAHDI-JYM again or on a new phone. Progress photos stay on this phone.': 'Séances, programme, pas, eau, poids et réglages sont enregistrés dans votre compte Google via la sauvegarde Android. Android les envoie en arrière-plan, généralement en quelques heures, et les restaure quand vous réinstallez MAHDI-JYM ou sur un nouveau téléphone. Les photos de progression restent sur ce téléphone.',
