  "Google Drive isn’t switched on for this app yet": "Google Drive n’est pas encore activé pour cette app",
  "That needs a one-time setup in Google Cloud by the app’s owner. Until then everything is saved through Android Backup — nothing is lost.": "Il faut une configuration unique dans Google Cloud par le propriétaire de l’app. D’ici là, tout est sauvegardé via Android Backup : rien n’est perdu.",
  "How to switch on Google Drive": "Comment activer Google Drive",
