  "Automatic versions": "Versions automatiques",
  "Once a day, when something changed, a full copy is kept on this phone and in Google Drive. The newest ones are kept; older ones are removed.": "Une fois par jour, si quelque chose a changé, une copie complète est gardée sur ce téléphone et dans Google Drive. Les plus récentes sont conservées, les anciennes supprimées.",
  "Once a day, when something changed, a full copy is kept on this phone. The newest ones are kept; older ones are removed.": "Une fois par jour, si quelque chose a changé, une copie complète est gardée sur ce téléphone. Les plus récentes sont conservées, les anciennes supprimées.",
  "Save a version every day": "Enregistrer une version chaque jour",
