  "In Google Drive": "Dans Google Drive",
  "Refresh": "Actualiser",
  "Loading…": "Chargement…",
  "Could not reach Google Drive — check the connection.": "Google Drive injoignable : vérifiez la connexion.",
  "No versions in Drive yet.": "Pas encore de version dans Drive.",
  "A version is a full copy: workouts, plan, routines, steps, water, body weight, health log and settings. Progress photos stay where they are. For a copy you can keep anywhere, use Export in Settings.": "Une version est une copie complète : séances, plan, routines, pas, eau, poids, journal santé et réglages. Les photos de progression restent où elles sont. Pour une copie à garder n’importe où, utilisez Exporter dans les réglages.",
  "Open console.cloud.google.com with your Google account and create a project (any name).": "Ouvrez console.cloud.google.com avec votre compte Google et créez un projet (n’importe quel nom).",
  "APIs & Services → Library → search “Google Drive API” → Enable.": "APIs & Services → Library → cherchez « Google Drive API » → Enable.",
  "OAuth consent screen → External → fill in the app name and your email → add the scope …/auth/drive.appdata → add your own account as a test user.": "OAuth consent screen → External → indiquez le nom de l’app et votre e-mail → ajoutez la portée …/auth/drive.appdata → ajoutez votre compte comme utilisateur test.",
  "Credentials → Create credentials → OAuth client ID → Android → paste the package name and SHA-1 below.": "Credentials → Create credentials → OAuth client ID → Android → collez le nom du paquet et le SHA-1 ci-dessous.",
  "Wait about 5 minutes, then come back here and tap Try again. Nothing changes in the app itself.": "Attendez environ 5 minutes, revenez ici et touchez Réessayer. Rien ne change dans l’app elle-même.",
  "Switch on Google Drive": "Activer Google Drive",
  "Only needed once, by the app’s owner. Saving through Android Backup keeps working the whole time.": "Nécessaire une seule fois, par le propriétaire de l’app. La sauvegarde via Android Backup continue de fonctionner.",
