  // 4.1 — Google check, today’s workout linked to the scale
  "The Google Drive API is switched off in the Cloud project": "L’API Google Drive est désactivée dans le projet Cloud",
  "In Google Cloud: APIs & Services → Library → Google Drive API → Enable. Then test again in a few minutes.": "Dans Google Cloud : API et services → Bibliothèque → Google Drive API → Activer. Puis retestez dans quelques minutes.",
  "Google doesn’t know this app yet": "Google ne connaît pas encore cette appli",
  "Create an Android OAuth client in Google Cloud with exactly the package name and SHA-1 shown here. Wait about 5 minutes, then test again.": "Créez dans Google Cloud un client OAuth Android avec exactement le nom de package et le SHA-1 affichés ici. Attendez environ 5 minutes, puis retestez.",
  "Access to Google Drive wasn’t allowed": "L’accès à Google Drive n’a pas été autorisé",
  "Tap Test Google Drive and choose Allow. While the app is in testing, your account must be listed as a test user on the OAuth consent screen.": "Touchez « Tester Google Drive » et choisissez Autoriser. Tant que l’appli est en test, votre compte doit figurer comme utilisateur test sur l’écran de consentement OAuth.",
  "Google refused access for this account": "Google a refusé l’accès pour ce compte",
  "On the OAuth consent screen: user type External, your account added as a test user, and the scope …/auth/drive.appdata added. Then test again.": "Sur l’écran de consentement OAuth : type d’utilisateur Externe, votre compte ajouté comme utilisateur test et le champ …/auth/drive.appdata ajouté. Puis retestez.",
