  "{0}th percentile": "{0}e percentile",
  "For under-18s the healthy weight follows the growth charts for the age: the middle (50th percentile) is the ideal, the 5th–85th the healthy range. It grows with you every year.": "Avant 18 ans, le poids sain suit les courbes de croissance pour l'âge : le milieu (50e percentile) est l'idéal, du 5e au 85e la plage saine. Il grandit avec toi chaque année.",
  "Age {0}": "Âge {0}",
  "For children and teens body fat is estimated from BMI and age.": "Chez l'enfant et l'ado, la masse grasse est estimée à partir de l'IMC et de l'âge.",
  "Gentle for a growing body: at most 250 kcal less a day from age 13, none before — more play and movement instead.": "Doux pour un corps qui grandit : au plus 250 kcal de moins par jour dès 13 ans, rien avant — plutôt plus de jeu et de mouvement.",
  "Protein {0} g per kg · fat about a third of the calories · carbs the rest.": "Protéines {0} g par kg · lipides environ un tiers des calories · glucides le reste.",
