  "Used MAHDI-JYM before? Pick your backup file.": "Vous avez déjà utilisé MAHDI-JYM ? Choisissez votre fichier de sauvegarde.",
  "Save to your Google Drive too": "Enregistrer aussi dans votre Google Drive",
  "Your data is already saved to your Google account through Android Backup. Add a file in your own Google Drive that you can see, and that is updated with every change — no setup.": "Vos données sont déjà enregistrées dans votre compte Google via la sauvegarde Android. Ajoutez un fichier visible dans votre propre Google Drive, mis à jour à chaque modification — sans configuration.",
  "The Google Drive app isn’t installed — install it to see Drive in the window.": "L’application Google Drive n’est pas installée — installez-la pour voir Drive dans la fenêtre.",
  "Get Google Drive": "Installer Google Drive",
  "Choose Google Drive": "Choisir Google Drive",
  "Choose the place in the window that appears.": "Choisissez l’emplacement dans la fenêtre qui s’ouvre.",
  "Data found in the file": "Données trouvées dans le fichier",
  "The file has MAHDI-JYM data, and this phone has some too. Which one do you want to keep?": "Le fichier contient des données MAHDI-JYM, et ce téléphone aussi. Lesquelles garder ?",
  "Use the file’s data": "Utiliser les données du fichier",
  "Welcome back": "Bon retour",
  "Your data was restored from Google Drive. Every change is saved back to the same file.": "Vos données ont été restaurées depuis Google Drive. Chaque modification est enregistrée dans le même fichier.",
  "Saved to your Google Drive in {0}. Every change is saved there automatically.": "Enregistré dans votre Google Drive dans {0}. Chaque modification y est enregistrée automatiquement.",
  "Your data stays on this phone and in your Google Drive. Changes are no longer saved to your Google account or to the Drive file.": "Vos données restent sur ce téléphone et dans votre Google Drive. Les modifications ne sont plus enregistrées dans votre compte Google ni dans le fichier Drive.",
  "Every change is written to your file a moment after you make it. Sign in with Google as well to also keep a copy through Android Backup.": "Chaque modification est écrite dans votre fichier quelques instants après. Connectez-vous aussi avec Google pour garder une copie via la sauvegarde Android.",
  "Saved to your file": "Enregistré dans votre fichier",
  "Drive app folder": "Dossier d’app Drive",
  "Google Drive file": "Fichier Google Drive",
  "Workouts, plan, steps, water, body weight and settings are saved to the file in your Google Drive and through Android Backup to your Google account. Progress photos stay on this phone.": "Séances, programme, pas, eau, poids et réglages sont enregistrés dans le fichier de votre Google Drive et, via la sauvegarde Android, dans votre compte Google. Les photos de progression restent sur ce téléphone.",
  "Saved to": "Enregistré dans",
  "Tap ☰ (the menu)": "Touchez ☰ (le menu)",
