  "Phone": "Téléphone",
  "In the phone settings the notifications are grouped: steps & activity, water, schedule & meals, workouts, health.": "Dans les réglages du téléphone, les notifications sont regroupées : pas et activité, eau, planning et repas, séances, santé.",
  "Sounds, banners and lock screen for each kind": "Sons, bannières et écran verrouillé pour chaque type",
  "Send a test notification": "Envoyer une notification de test",
  "School, meals, drinks, work": "École, repas, boissons, travail",
  "Food & drinks": "Repas et boissons",
  "Activity": "Activité",
  "Body & health": "Corps et santé",
  "Reports & reminders": "Rapports et rappels",
  "Reminders that show everything": "Des rappels qui montrent tout",
  "Arrange everything yourself — school, meals, drinks, work, prayer — on the days you choose, with an end time and your own notes.": "Organise tout toi-même — école, repas, boissons, travail, prière — les jours de ton choix, avec une heure de fin et tes propres notes.",
  "School Sunday to Thursday, 7:30 to 12:40, then lunch, rest, homework, work, drinks and dinner — and a calmer weekend.": "École du dimanche au jeudi, de 7 h 30 à 12 h 40, puis déjeuner, repos, devoirs, travail, boissons et dîner — et un week-end plus calme.",
  "Each reminder shows the time, your notes and the food and drinks you chose with their calories — with Done ✓ and In 10 min.": "Chaque rappel montre l’heure, tes notes et les repas et boissons choisis avec leurs calories — avec « Fait ✓ » et « Dans 10 min ».",
  "Colas, lemon-lime, fruit sodas, malt and energy drinks and homemade mojitos — in cans, bottles and glasses of every size, with sugar in teaspoons.": "Colas, citron-citron vert, sodas aux fruits, boissons maltées et énergisantes et mojitos maison — en canettes, bouteilles et verres de toutes tailles, avec le sucre en cuillères.",
  "Pistachios, almonds, walnuts, cashews, the seeds you crack and kerzat — raw, roasted or salted, by the handful, with what each is good for.": "Pistaches, amandes, noix, cajous, les graines à croquer et le kerzat — crus, grillés ou salés, par poignée, avec leurs bienfaits.",
  "All notifications in one place": "Toutes les notifications au même endroit",
  "Which reminders are on, what still rings today, and the phone’s notification settings grouped by kind.": "Quels rappels sont activés, ce qui sonne encore aujourd’hui, et les réglages de notifications du téléphone regroupés par type.",
  "Smoother everywhere": "Plus fluide partout",
