  "Values per 100 g of the edible part, rounded. Roasting removes water, so roasted nuts have a few more calories per gram.": "Valeurs pour 100 g de partie comestible, arrondies. La torréfaction retire de l'eau : les noix grillées ont un peu plus de calories par gramme.",
