  "Colas": "Colas",
  "Regular colas are high in sugar and have some caffeine. The zero versions have no calories.": "Les colas classiques sont très sucrés et contiennent un peu de caféine. Les versions zéro n'ont pas de calories.",
  "Lemon & lime": "Citron & citron vert",
  "No caffeine, but just as sweet as cola — the diet versions have no sugar.": "Pas de caféine, mais aussi sucré que le cola — les versions light sont sans sucre.",
  "Fruit sodas": "Sodas aux fruits",
  "Coloured and sweet, usually with no real fruit. Sparkling water with fresh juice is a lighter choice.": "Colorés et sucrés, souvent sans vrai fruit. L'eau pétillante avec du jus frais est plus légère.",
  "Soda & sparkling water": "Soda et eau pétillante",
  "Soda and sparkling water have no calories. Tonic water and ginger ale are sweetened.": "Le soda et l'eau pétillante n'ont pas de calories. Le tonic et le ginger ale sont sucrés.",
  "Malt drinks 0.0%": "Boissons maltées 0,0 %",
  "Malt drinks have no alcohol. The flavoured ones are as sweet as soft drinks; the classic is lighter.": "Les boissons maltées sont sans alcool. Les aromatisées sont aussi sucrées qu'un soda ; la classique est plus légère.",
  "Energy drinks": "Boissons énergisantes",
  "Lots of caffeine and sugar. Not for children, pregnancy or anyone sensitive to caffeine — one can a day at most.": "Beaucoup de caféine et de sucre. Pas pour les enfants, la grossesse ou les personnes sensibles à la caféine — une canette par jour au maximum.",
  "Homemade sodas": "Sodas maison",
  "Made at home with soda water, fresh lemon and mint — you decide how sweet. Values assume a little sugar.": "Faits maison avec de l'eau gazeuse, du citron frais et de la menthe — vous choisissez le sucre. Valeurs calculées avec un peu de sucre.",
  "High in caffeine — not for children, pregnancy or anyone sensitive to caffeine. Never mix it with alcohol, and not during hard exercise in the heat.": "Riche en caféine — pas pour les enfants, la grossesse ou les personnes sensibles à la caféine. Ne jamais mélanger avec de l'alcool, ni en plein effort par forte chaleur.",
  "No sugar: sweetened with sweeteners, so almost no calories.": "Sans sucre : sucré aux édulcorants, donc presque sans calories.",
  "Contains quinine, which gives the bitter taste.": "Contient de la quinine, qui donne le goût amer.",
