  "Tea with fresh mint from the garden, after lunch.": "Du thé à la menthe fraîche du jardin, après le déjeuner.",
  "Hot cocoa on cold Baghdad winter evenings.": "Un chocolat chaud pour les soirées d’hiver à Bagdad.",
  "Warm milk sweetened with date syrup — a winter comfort.": "Du lait chaud sucré au sirop de datte — un réconfort d’hiver.",
  "Small and strong, sipped slowly after a meal or with guests.": "Petit et corsé, à siroter après le repas ou avec des invités.",
  "The quick coffee of students and late-night studying.": "Le café express des élèves et des révisions tardives.",
