  "Your school week, your times": "Ta semaine d’école, tes horaires",
  "Up at 7:00, water, breakfast, get ready, school 7:30–12:40 with nothing inside it, home, water, lunch and a drink — then a nap, homework, games, review, sport, dinner with water and a light snack before bed.": "Lever à 7:00, eau, petit-déjeuner, préparation, école 7:30–12:40 sans rien au milieu, retour, eau, déjeuner et une boisson — puis sieste, devoirs, jeux, révisions, sport, dîner avec de l’eau et un en-cas léger avant de dormir.",
  "Friday and Saturday too": "Vendredi et samedi aussi",
  "Sleep in, an Iraqi breakfast, study, phone & games, helping at home, football, family and rest — every block with its calories.": "Grasse matinée, petit-déjeuner irakien, études, téléphone et jeux, aide à la maison, foot, famille et repos — chaque bloc avec ses calories.",
  "Many more nuts, with Iraqi names": "Beaucoup plus de fruits secs, avec leurs noms irakiens",
  "Melon seeds, lemon pistachios, acorns, royal and seed kerzat, shamiya, termis — and dried fruits and dates: zbeeb, kishmish, zahdi, khastawi, barhi, figs, qamar al-din, mlabbas and more.": "Graines de melon, pistaches au citron, glands, kerzat royal et de graines, shamiya, termis — et fruits secs et dattes : zbib, kichmich, zahdi, khastawi, barhi, figues, qamar al-din, mlabbas et plus.",
  "More Iraqi drinks": "Plus de boissons irakiennes",
  "Chai haleeb, mint and lemon tea, kakao, milk with dibis, Turkish coffee, Nescafé, hamudh hilu and the juice shop: orange, carrot, apple, grape, mango, banana and strawberry milk and the Iraqi cocktail.": "Chaï halib, thé à la menthe et au citron, kakao, lait au dibis, café turc, Nescafé, hamoudh hilou et le bar à jus : orange, carotte, pomme, raisin, mangue, laits banane et fraise et le cocktail irakien.",
  "Everyday Iraqi food": "La cuisine irakienne de tous les jours",
  "Eggs with samoon, cheese and labneh sandwiches, timman with fasolia or bamia, sheikh mahshi, shifta, makarona, amba, arnoos — and foods can go straight into your schedule.": "Œufs et samoun, sandwichs au fromage et au labné, timman avec fasolia ou bamia, cheikh mahchi, chifta, makarona, amba, arnous — et les aliments vont directement dans ton planning.",
  "A real profile picture": "Une vraie photo de profil",
  "Your own photo from the phone, or one of hundreds of symbols — faces, sport, animals, nature, food, Iraq — on 24 colours.": "Ta propre photo depuis le téléphone, ou l’un des centaines de symboles — visages, sport, animaux, nature, nourriture, Irak — sur 24 couleurs.",
  "All your steps as a walk across Iraq, city by city — and the last five weeks at a glance.": "Tous tes pas comme une marche à travers l’Irak, ville après ville — et les cinq dernières semaines d’un coup d’œil.",
  "Water, any amount": "L’eau, en n’importe quelle quantité",
  "Add any amount up to a 1.5 L bottle, and see if you are ahead or behind right now.": "Ajoute n’importe quelle quantité jusqu’à une bouteille de 1,5 L, et vois si tu es en avance ou en retard maintenant.",
  "Iraq themes": "Thèmes Irak",
  "The Tigris, the Euphrates, Ishtar blue, Baghdad nights, Basra palms, Mosul marble, the marshes and more — 1,442 themes in all.": "Le Tigre, l’Euphrate, bleu d’Ishtar, nuits de Bagdad, palmiers de Bassorah, marbre de Mossoul, les marais et plus — 1 442 thèmes au total.",
  "No more buzzing on every tap": "Plus de vibration à chaque toucher",
  "The light vibration when you tap or swipe is off — switch it back on in Settings if you liked it.": "La légère vibration au toucher ou au balayage est désactivée — réactive-la dans les Réglages si tu l’aimais.",
